<?php declare(strict_types=1); namespace App\People\Application\Command\CreateRelationship; use App\People\Domain\Model\PersonRelationship; use App\People\Domain\Repository\PersonRepository; use App\People\Domain\Repository\RelationshipRepository; use App\People\Domain\ValueObject\PersonId; use App\People\Domain\ValueObject\RelationshipId; use App\People\Domain\Enum\RelationshipType; #[\Symfony\Component\Messenger\Attribute\AsMessageHandler]
final readonly class CreateRelationshipHandler {public function __construct(private RelationshipRepository $relationships,private PersonRepository $people){} public function __invoke(CreateRelationshipCommand $c):RelationshipId{$p=PersonId::fromString($c->personId);$r=PersonId::fromString($c->relatedPersonId);if(!$this->people->exists($p)||!$this->people->exists($r))throw new \RuntimeException('Both people must exist.');$id=RelationshipId::generate();$this->relationships->save(PersonRelationship::create($id,$p,$r,RelationshipType::from($c->type),new \DateTimeImmutable()));return $id;}}
